import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {pathToFileURL} from 'node:url';
const root=process.cwd(), styles=path.join(root,'src/renderer/src/styles');
const sass=await import(pathToFileURL(path.join(root,'node_modules/sass/sass.node.mjs')));
const {default:postcss}=await import(pathToFileURL(path.join(root,'node_modules/postcss/lib/postcss.mjs')));
const temporary=fs.mkdtempSync('/private/tmp/orbit-composer-css-');
fs.cpSync(styles,temporary,{recursive:true});
fs.writeFileSync(path.join(temporary,'_composer.scss'),execFileSync('git',['show','e0a1b70684fc719b578dab9d72b25e48451a09e2:src/renderer/src/styles/_composer.scss'],{cwd:root}));
const before=sass.compile(path.join(temporary,'main.scss'),{style:'expanded'}).css;
const after=sass.compile(path.join(styles,'main.scss'),{style:'expanded'}).css;
const vector=css=>{const rules=[];postcss.parse(css).walkRules(rule=>{const context=[];for(let p=rule.parent;p&&p.type!=='root';p=p.parent)if(p.type==='atrule')context.unshift([p.name,p.params]);rules.push([rule.selector,context,rule.nodes.filter(n=>n.type==='decl').map(d=>[d.prop,d.value,Boolean(d.important)])]);});return rules;};
const hash=s=>crypto.createHash('sha256').update(s).digest('hex');
const a=JSON.stringify(vector(before)),b=JSON.stringify(vector(after));
console.log(JSON.stringify({beforeBytes:Buffer.byteLength(before),afterBytes:Buffer.byteLength(after),beforeCSSSHA256:hash(before),afterCSSSHA256:hash(after),orderedRules:vector(before).length,beforeOrderedVectorSHA256:hash(a),afterOrderedVectorSHA256:hash(b),bytesIdentical:before===after,vectorsIdentical:a===b,temporary},null,2));
if(before!==after||a!==b)process.exitCode=1;
